package com.wipro.spring; import org.springframework.stereotype.Controller; import org.springframework.web.bind.annotation.*; import org.springframework.jdbc.core.JdbcTemplate; @Controller public class StudentController { private final JdbcTemplate jdbc; public StudentController(JdbcTemplate jdbc){this.jdbc=jdbc;} @GetMapping("/") public String form(){return "index";} @PostMapping("/save") public String save(@RequestParam String studentId,@RequestParam String studentName,@RequestParam String email){jdbc.update("INSERT INTO STUDENT(STUDENT_ID,STUDENT_NAME,EMAIL) VALUES(?,?,?)",studentId,studentName,email);return "success";} }